 async function showPage(number){const s=session;if(!s?.doc||s.busy||number<1||number>s.doc.numPages)return;s.page=number;try{const rendered=await renderPageCanvas(s.doc,number,1.2);if(session!==s)return;s.baseCanvas=rendered.canvas;$('#pdfCanvasWrap',dialog).hidden=false;$('#pdfPreviewEmpty',dialog).hidden=true;$('#pdfPreviewNav',dialog).hidden=false;$('#pdfPageInfo',dialog).textContent=`${s.page} / ${s.doc.numPages} 页`;$('#pdfPreviewHint',dialog).textContent=s.tool.id==='pdf-redact'?'拖动框选，永久移除区域内容':['pdf-edit','pdf-sign'].includes(s.tool.id)?'点击页面设置添加位置':'';$('#pdfPrev',dialog).disabled=s.page===1;$('#pdfNext',dialog).disabled=s.page===s.doc.numPages;paint();}catch(error){if(!s.busy)alert(error.message,true);}}
