 function wireCanvas(){const canvas=$('#pdfCanvas',dialog),wrap=$('#pdfCanvasWrap',dialog),box=$('#pdfSelectionBox',dialog);let start=null;const point=event=>{const rect=canvas.getBoundingClientRect();return{x:Math.min(1,Math.max(0,(event.clientX-rect.left)/rect.width)),y:Math.min(1,Math.max(0,(event.clientY-rect.top)/rect.height))};};canvas.onpointerdown=event=>{if(session.busy)return;if(session.tool.id==='pdf-redact'){start=point(event);canvas.setPointerCapture(event.pointerId);event.preventDefault();}else if(['pdf-edit','pdf-sign'].includes(session.tool.id)){const p=point(event);session.options.x=Math.round(p.x*100);session.options.y=Math.round(p.y*100);$('[data-option="x"]',dialog).value=session.options.x;$('[data-option="y"]',dialog).value=session.options.y;paint();invalidate();}};canvas.onpointermove=event=>{if(!start)return;const p=point(event);box.hidden=false;box.style.left=Math.min(start.x,p.x)*100+'%';box.style.top=Math.min(start.y,p.y)*100+'%';box.style.width=Math.abs(p.x-start.x)*100+'%';box.style.height=Math.abs(p.y-start.y)*100+'%';};canvas.onpointerup=event=>{if(!start)return;const p=point(event),r={page:session.page,x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(start.x-p.x),h:Math.abs(start.y-p.y)};start=null;box.hidden=true;if(r.w>.008&&r.h>.008){session.options.redactions.push(r);updateRedactions();paint();invalidate();}};canvas.onpointercancel=()=>{start=null;box.hidden=true;};}
