 function wireSignature(){const canvas=$('#signaturePad',dialog),ctx=canvas.getContext('2d');ctx.lineWidth=3;ctx.lineCap='round';ctx.strokeStyle='#172e22';let drawing=false;const p=event=>{const r=canvas.getBoundingClientRect();return[(event.clientX-r.left)/r.width*canvas.width,(event.clientY-r.top)/r.height*canvas.height];};canvas.onpointerdown=event=>{if(session.busy)return;drawing=true;canvas.setPointerCapture(event.pointerId);ctx.beginPath();ctx.moveTo(...p(event));event.preventDefault();};canvas.onpointermove=event=>{if(drawing){ctx.lineTo(...p(event));ctx.stroke();}};canvas.onpointerup=()=>{if(drawing){session.options.signature=canvas.toDataURL('image/png');drawing=false;invalidate();}};canvas.onpointercancel=()=>{drawing=false;};$('#clearSignature',dialog).onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);session.options.signature=null;invalidate();};}
